package com.arena.core.publicclub;
import static com.arena.core.publicclub.PublicClubContracts.*;
import com.arena.core.training.*;import com.arena.core.sessions.*;import com.arena.core.exception.*;
import java.time.*;import java.util.*;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.oauth2.jwt.Jwt;
@Service @Transactional @RequiredArgsConstructor
public class PublicReservationService {
 @org.springframework.beans.factory.annotation.Value("${arena.public.reservation-requests-enabled:false}") private boolean reservationRequestsEnabled;
 private void requireEnabled(){if(!reservationRequestsEnabled)throw new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND);}
 private final PublicClubService clubs;private final ClubPublicSiteRepository sites;private final ClubReservationRequestRepository requests;private final AcademyAuthorization auth;private final AcademyPlayAreaRepository areas;private final AcademySportRepository sports;private final RunningSessionService sessions;
 public BookingReceipt request(String slug,Booking r){requireEnabled();var site=clubs.resolve(slug);site=sites.locked(site.getAcademyId()).orElseThrow();String name=ClubCustomerService.name(r.name());String mobile;
  try{mobile=ClubCustomerService.mobile(r.mobile());}catch(ArenaOpsException e){if(e.getErrorCode()!=ErrorCode.INVALID_REQUEST)throw e;throw new ArenaOpsException(ErrorCode.PUBLIC_BOOKING_INVALID_MOBILE);}
  if(!r.privacyAccepted()||r.requestId()==null||r.website()!=null&&!r.website().isBlank())throw new ArenaOpsException(ErrorCode.PUBLIC_BOOKING_INVALID_DETAILS);String fingerprint=ClubCustomerService.hash(r.facilityId()+"|"+r.start()+"|"+r.duration()+"|"+name+"|"+mobile);var old=requests.findByAcademyIdAndRequestId(site.getAcademyId(),r.requestId());if(old.isPresent()){if(!fingerprint.equals(old.get().getRequestHash()))throw new ArenaOpsException(ErrorCode.CONFLICT);return new BookingReceipt(old.get().getStatus(),old.get().getReference());}
  clubs.bookingWindow(site,r.start(),r.duration());var f=areas.locked(site.getAcademyId(),r.facilityId()).filter(v->clubs.eligible(v,sports.findByAcademyIdOrderByName(v.getAcademyId()))).orElseThrow(()->new ArenaOpsException(ErrorCode.PUBLIC_BOOKING_FACILITY_UNAVAILABLE));
  try{sessions.validatePublicWindow(site.getAcademyId(),f.getId(),r.start(),r.start().plusMinutes(r.duration()));}catch(ArenaOpsException e){if(e.getErrorCode()!=ErrorCode.CONFLICT)throw e;throw new ArenaOpsException(ErrorCode.PUBLIC_BOOKING_CONFLICT);}
  var now=Instant.now();String hash=ClubCustomerService.hash(mobile);if(requests.countByAcademyIdAndMobileHashAndCreatedAtAfter(site.getAcademyId(),hash,now.minusSeconds(1800))>=2||requests.countByAcademyIdAndFacilityIdAndCreatedAtAfter(site.getAcademyId(),f.getId(),now.minusSeconds(1800))>=6)throw new ArenaOpsException(ErrorCode.TOO_MANY_REQUESTS);
  var v=new ClubReservationRequest();v.setAcademyId(site.getAcademyId());v.setFacilityId(f.getId());v.setRequestId(r.requestId());v.setRequestHash(fingerprint);v.setReference(UUID.randomUUID().toString());v.setCustomerName(name);v.setMobile(mobile);v.setMobileHash(hash);v.setStatus("PENDING");v.setReservedStart(r.start());v.setReservedEnd(r.start().plusMinutes(r.duration()));v.setCreatedAt(now);v.setExpiresAt(now.plusSeconds(1800));requests.saveAndFlush(v);return new BookingReceipt("PENDING",v.getReference());
 }
 public List<BookingPending> pending(Jwt jwt){requireEnabled();var a=auth.manage(jwt);return requests.findTop100ByAcademyIdAndStatusAndExpiresAtAfterOrderByCreatedAtAsc(a.academyId(),"PENDING",Instant.now()).stream().map(r->new BookingPending(r.getId(),areas.findById(r.getFacilityId()).orElseThrow().getCode(),r.getCustomerName(),r.getMobile(),r.getReservedStart(),r.getReservedEnd(),r.getExpiresAt())).toList();}
 public void decide(Jwt jwt,Long id,boolean approve){requireEnabled();var a=auth.manage(jwt);var r=requests.locked(a.academyId(),id).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND));if(!"PENDING".equals(r.getStatus())||!r.getExpiresAt().isAfter(Instant.now()))throw new ArenaOpsException(ErrorCode.INVALID_STATE);if(approve){var site=sites.findById(a.academyId()).filter(ClubPublicSite::isPublished).orElseThrow(()->new ArenaOpsException(ErrorCode.INVALID_STATE));clubs.bookingWindow(site,r.getReservedStart(),(int)Duration.between(r.getReservedStart(),r.getReservedEnd()).toMinutes());var session=sessions.reserve(jwt,new RunningSessionContracts.Reserve(r.getFacilityId(),r.getCustomerName(),r.getReservedStart(),r.getReservedEnd()));r.setSessionId(session.id());r.setStatus("APPROVED");r.setExpiresAt(r.getReservedEnd().atZone(ZoneId.of(clubs.usable(site).getTrainingTimezone())).toInstant());}else{r.setStatus("REJECTED");r.setCustomerName(null);r.setMobile(null);}r.setDecidedAt(Instant.now());r.setDecidedBy(a.user().getUsername());requests.save(r);}
 @org.springframework.scheduling.annotation.Scheduled(fixedDelayString="${arena.checkin.cleanup-ms:300000}")public void cleanup(){var now=Instant.now();requests.expire(now);requests.scrub(now.minusSeconds(86400));requests.purge(now.minusSeconds(86400));}
}
